import * as React from "react"
import { graphql } from "gatsby"
import { GatsbyImage } from "gatsby-plugin-image"
import { NavBar } from "../components/navbar"
import "../components/about.css"

const About = ({ data }) => {
  const [activeTab, setActiveTab] = React.useState("photography")
  const [lightbox, setLightbox] = React.useState({ index: null, dir: 1 })
  const [imgLoading, setImgLoading] = React.useState(false)
  const [tabDir, setTabDir] = React.useState(1)
  const [prevTab, setPrevTab] = React.useState(null)

  const galleries = {
    photography: {
      label: "Photography",
      images: data.photography.nodes,
      emptyMessage: "Photos coming soon - add images to src/images/photography/",
    },
    digitalArt: {
      label: "Digital Art",
      images: data.digitalArt.nodes,
      emptyMessage: "Artwork coming soon - add images to src/images/digital-art/",
    },
  }

  const activeGallery = galleries[activeTab]
  const images = activeGallery.images
  const lightboxOpen = lightbox.index !== null

  const openLightbox = index => setLightbox({ index, dir: 1 })
  const closeLightbox = () => setLightbox({ index: null, dir: 1 })
  const stepLightbox = React.useCallback(
    delta =>
      setLightbox(prev => ({
        index: (prev.index + delta + images.length) % images.length,
        dir: delta,
      })),
    [images.length]
  )

  const switchTab = key => {
    if (key === activeTab) return
    const order = Object.keys(galleries)
    setTabDir(order.indexOf(key) > order.indexOf(activeTab) ? 1 : -1)
    setPrevTab(activeTab)
    setActiveTab(key)
    closeLightbox()
  }

  const renderGalleryContent = (tabKey, isExiting) => {
    const gallery = galleries[tabKey]
    return gallery.images.length > 0 ? (
      <div className="hobby-gallery">
        {gallery.images.map((node, index) => (
          <button
            className="hobby-gallery-item"
            key={node.id}
            onClick={() => !isExiting && openLightbox(index)}
            tabIndex={isExiting ? -1 : 0}
            aria-label={`View ${node.name} full size`}
          >
            <GatsbyImage
              image={node.childImageSharp.thumb}
              alt={node.name}
              className="hobby-gallery-img"
            />
          </button>
        ))}
      </div>
    ) : (
      <p className="hobby-empty">{gallery.emptyMessage}</p>
    )
  }

  React.useEffect(() => {
    if (lightboxOpen) setImgLoading(true)
  }, [lightbox.index, lightboxOpen])

  React.useEffect(() => {
    if (!lightboxOpen) return
    const onKeyDown = e => {
      if (e.key === "Escape") closeLightbox()
      if (e.key === "ArrowRight") stepLightbox(1)
      if (e.key === "ArrowLeft") stepLightbox(-1)
    }
    window.addEventListener("keydown", onKeyDown)
    document.body.style.overflow = "hidden"
    return () => {
      window.removeEventListener("keydown", onKeyDown)
      document.body.style.overflow = ""
    }
  }, [lightboxOpen, stepLightbox])

  return (
    <main>
      
      <div className="landing">
      <NavBar></NavBar>
      
      <div className="about-content">
        <h1> About me </h1>
        <p className="about-opening">
          Hello! I'm Barbara - welcome to my little corner of the internet.
          When I'm not writing code, you'll find me behind a camera lens or
          drawing on my tablet.
        </p>

        <div className="hobby-window">
          <div className="hobby-toggle" role="tablist">
            {Object.entries(galleries).map(([key, gallery]) => (
              <button
                key={key}
                role="tab"
                aria-selected={activeTab === key}
                className={`hobby-tab ${activeTab === key ? "hobby-tab-active" : ""}`}
                onClick={() => switchTab(key)}
              >
                {gallery.label}
              </button>
            ))}
          </div>

          <div className="hobby-panel-stack">
            {prevTab && (
              <div
                className={`hobby-gallery-panel hobby-panel-exit ${
                  tabDir >= 0 ? "hobby-panel-exit-left" : "hobby-panel-exit-right"
                }`}
                key={prevTab}
                aria-hidden="true"
                onAnimationEnd={() => setPrevTab(null)}
              >
                {renderGalleryContent(prevTab, true)}
              </div>
            )}
            <div
              className={`hobby-gallery-panel ${
                tabDir >= 0 ? "hobby-panel-swipe-right" : "hobby-panel-swipe-left"
              }`}
              key={activeTab}
            >
              {renderGalleryContent(activeTab, false)}
            </div>
          </div>
        </div>
      </div>
      </div>

      {lightboxOpen && (
        <div className="lightbox-overlay" onClick={closeLightbox} role="dialog" aria-modal="true">
          <button
            className="lightbox-close"
            onClick={closeLightbox}
            aria-label="Close slideshow"
          >
            &times;
          </button>

          <div className="lightbox-main" onClick={e => e.stopPropagation()}>
            <button
              className="lightbox-arrow lightbox-arrow-left"
              onClick={() => stepLightbox(-1)}
              aria-label="Previous image"
            >
              <svg viewBox="0 0 24 24" className="lightbox-arrow-svg" aria-hidden="true">
                <path
                  d="M15 5 L9 12 L15 19"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>

            <div
              className={`lightbox-image-wrapper ${
                imgLoading
                  ? ""
                  : lightbox.dir >= 0
                  ? "lightbox-pop-right"
                  : "lightbox-pop-left"
              }`}
              key={`${activeTab}-${lightbox.index}`}
            >
              {imgLoading && (
                <div className="cat-loader" aria-label="Loading image">
                  <svg
                    className="cat-loader-spinner"
                    viewBox="0 0 100 100"
                    aria-hidden="true"
                  >
                    <path
                      className="cat-loader-outline"
                      d="M18,52 C18,42 20,37 23,34 L19,21 Q17,13 24,15 L40,23 C46,20 54,20 60,23 L76,15 Q83,13 81,21 L77,34 C80,37 82,42 82,52 C82,68 68,76 50,76 C32,76 18,68 18,52 Z"
                      pathLength="100"
                    />
                    <path
                      className="cat-loader-spark cat-loader-trail-2"
                      d="M18,52 C18,42 20,37 23,34 L19,21 Q17,13 24,15 L40,23 C46,20 54,20 60,23 L76,15 Q83,13 81,21 L77,34 C80,37 82,42 82,52 C82,68 68,76 50,76 C32,76 18,68 18,52 Z"
                      pathLength="100"
                    />
                    <path
                      className="cat-loader-spark cat-loader-trail-1"
                      d="M18,52 C18,42 20,37 23,34 L19,21 Q17,13 24,15 L40,23 C46,20 54,20 60,23 L76,15 Q83,13 81,21 L77,34 C80,37 82,42 82,52 C82,68 68,76 50,76 C32,76 18,68 18,52 Z"
                      pathLength="100"
                    />
                    <path
                      className="cat-loader-spark"
                      d="M18,52 C18,42 20,37 23,34 L19,21 Q17,13 24,15 L40,23 C46,20 54,20 60,23 L76,15 Q83,13 81,21 L77,34 C80,37 82,42 82,52 C82,68 68,76 50,76 C32,76 18,68 18,52 Z"
                      pathLength="100"
                    />
                  </svg>
                  <p className="cat-loader-text">loading...</p>
                </div>
              )}
              <img
                src={images[lightbox.index].childImageSharp.full.src}
                alt={images[lightbox.index].name}
                className="lightbox-image"
                style={{ display: imgLoading ? "none" : "block" }}
                onLoad={() => setImgLoading(false)}
                onError={() => setImgLoading(false)}
              />
            </div>

            <button
              className="lightbox-arrow lightbox-arrow-right"
              onClick={() => stepLightbox(1)}
              aria-label="Next image"
            >
              <svg viewBox="0 0 24 24" className="lightbox-arrow-svg" aria-hidden="true">
                <path
                  d="M9 5 L15 12 L9 19"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="3"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          </div>

          <div className="lightbox-thumbs" onClick={e => e.stopPropagation()}>
            {images.map((node, index) => (
              <button
                className={`lightbox-thumb ${
                  index === lightbox.index ? "lightbox-thumb-active" : ""
                }`}
                key={node.id}
                onClick={() =>
                  setLightbox(prev => ({ index, dir: index >= prev.index ? 1 : -1 }))
                }
                aria-label={`View ${node.name}`}
              >
                <GatsbyImage
                  image={node.childImageSharp.thumb}
                  alt={node.name}
                  className="lightbox-thumb-img"
                />
              </button>
            ))}
          </div>
        </div>
      )}
    </main>
  )
}

export const pageQuery = graphql`
  query AboutGalleries {
    photography: allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "photography" }
        ext: { regex: "/\\.(jpe?g|png|webp)$/i" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        id
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 600)
          full: resize(width: 2000, quality: 90) {
            src
          }
        }
      }
    }
    digitalArt: allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "digital-art" }
        ext: { regex: "/\\.(jpe?g|png|webp)$/i" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        id
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 600)
          full: resize(width: 2000, quality: 90) {
            src
          }
        }
      }
    }
  }
`

export default About

export const Head = () => <title>About</title>
